import importlib.util
import io
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
from contextlib import redirect_stdout

from Bio import SeqIO


SCRIPT = Path(__file__).resolve().parents[1] / "join_segments.py"
FASTA_COMBINE = SCRIPT.parent / "fasta_combine.py"
SPEC = importlib.util.spec_from_file_location("join_segments", SCRIPT)
join_segments = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(join_segments)


class JoinSegmentsTests(unittest.TestCase):
    def test_parse_gaf_path_preserves_realistic_node_names(self):
        steps = join_segments.parse_gaf_path(
            ">utig4-443<node.with-dots_1>tig0007"
        )
        self.assertEqual(
            steps,
            [
                ("segment", "utig4-443", "+"),
                ("segment", "node.with-dots_1", "-"),
                ("segment", "7", "+"),
            ],
        )

    def test_make_sequence_trims_graph_link_overlaps(self):
        cigars = {"a+|b+": "2M", "b+|c+": "1M"}
        segments = {"a": "AAAACC", "b": "CCGGGG", "c": "TTT"}
        steps = join_segments.parse_gaf_path(">a>b>c")

        sequence, circular = join_segments.make_sequence(cigars, segments, steps, -1)

        self.assertEqual(sequence, "AAAACCGGGGTT")
        self.assertFalse(circular)

    def test_main_reads_gaf_style_paths_and_writes_fasta(self):
        with tempfile.TemporaryDirectory() as directory:
            directory = Path(directory)
            paths = directory / "paths.gaf.tsv"
            gfa = directory / "graph.gfa"
            result = directory / "result.fasta"

            paths.write_text("name\tpath\tassignment\np1\t>a>b>c\tHAPLOTYPE1\n")
            gfa.write_text(
                "S\ta\tAAAACC\nS\tb\tCCGGGG\nS\tc\tTTT\n"
                "L\ta\t+\tb\t+\t2M\nL\tb\t+\tc\t+\t1M\n"
            )

            join_segments.main([str(gfa), str(paths), str(result)])

            with result.open() as fasta:
                records = list(SeqIO.parse(fasta, "fasta"))
            self.assertEqual([record.id for record in records], ["p1"])
            self.assertEqual(str(records[0].seq), "AAAACCGGGGTT")

    def test_main_writes_clean_fasta_to_stdout(self):
        with tempfile.TemporaryDirectory() as directory:
            directory = Path(directory)
            paths = directory / "paths.gaf.tsv"
            gfa = directory / "graph.gfa"
            paths.write_text("name\tpath\np1\t>a\n")
            gfa.write_text("S\ta\tAAAA\n")

            output = io.StringIO()
            with redirect_stdout(output):
                join_segments.main([str(gfa), str(paths)])

            self.assertEqual(">p1\nAAAA\n", output.getvalue())

    def test_fasta_rename_stream_is_clean(self):
        with tempfile.TemporaryDirectory() as directory:
            directory = Path(directory)
            name_map = directory / "names.tsv"
            name_map.write_text("path1\ttig00000001\n")

            result = subprocess.run(
                [
                    sys.executable,
                    str(FASTA_COMBINE),
                    "rename",
                    "-",
                    str(name_map),
                    "-",
                ],
                input=">path1\nAAAA\n",
                capture_output=True,
                text=True,
                check=True,
            )

            self.assertEqual(">tig00000001\nAAAA\n", result.stdout)
            self.assertIn("Starting file -.", result.stderr)

    def test_rejects_unoriented_and_malformed_paths(self):
        for path in ("utig4-1+", ">a[N2N", "[N2N]>a", ">a[N2N][N3N]>b"):
            with self.subTest(path=path):
                with self.assertRaises(ValueError):
                    join_segments.parse_gaf_path(path)


